import React from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery } from '@tanstack/react-query';
import axiosInstance from '../core/api/axiosConfig';
import {
  Box, Typography, Paper, Grid, Card, CardContent, Chip,
  List, ListItem, ListItemText, ListItemIcon, CircularProgress, Divider
} from '@mui/material';
import PeopleIcon from '@mui/icons-material/People';
import WarningAmberIcon from '@mui/icons-material/WarningAmber';
import DescriptionIcon from '@mui/icons-material/Description';
import AssignmentIcon from '@mui/icons-material/Assignment';
import PersonAddIcon from '@mui/icons-material/PersonAdd';
import TrendingDownIcon from '@mui/icons-material/TrendingDown';
import EventBusyIcon from '@mui/icons-material/EventBusy';
import useAuth from '../core/hooks/useAuth';
import useCompany from '../core/hooks/useCompany';
import { formatPersianNumber } from '../core/utils/numberUtils';

const StatCard = ({ title, value, icon, color }) => (
  <Grid item xs={12} sm={6} md={3}>
    <Card sx={{ height: '100%', borderLeft: `4px solid ${color}` }}>
      <CardContent>
        <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
          <Box sx={{ color, mr: 1.5 }}>{icon}</Box>
          <Typography variant="body2" color="textSecondary">{title}</Typography>
        </Box>
        <Typography variant="h4" fontWeight="bold">{formatPersianNumber(value ?? 0)}</Typography>
      </CardContent>
    </Card>
  </Grid>
);

const DashboardPage = () => {
  const { t } = useTranslation();
  const { user } = useAuth();
  const { currentCompany } = useCompany();

  const { data: stats, isLoading: loadingStats } = useQuery({
    queryKey: ['dashboard-stats'],
    queryFn: () => axiosInstance.get('/dashboard/stats/').then(r => r.data),
    refetchInterval: 5 * 60 * 1000,
  });

  const { data: alerts, isLoading: loadingAlerts } = useQuery({
    queryKey: ['dashboard-alerts'],
    queryFn: () => axiosInstance.get('/dashboard/alerts/').then(r => r.data),
    refetchInterval: 5 * 60 * 1000,
  });

  const { data: activities, isLoading: loadingActivities } = useQuery({
    queryKey: ['dashboard-activities'],
    queryFn: () => axiosInstance.get('/dashboard/recent-activities/').then(r => r.data),
    refetchInterval: 5 * 60 * 1000,
  });

  const loading = loadingStats || loadingAlerts || loadingActivities;

  if (loading) return <Box sx={{ textAlign: 'center', p: 6 }}><CircularProgress /></Box>;

  return (
    <Box>
      <Typography variant="h4" gutterBottom>{t('dashboard.welcome')}، {user?.first_name || user?.username}</Typography>
      {currentCompany && <Typography color="textSecondary" gutterBottom>{t('company.current')}: {currentCompany.name}</Typography>}

      {/* Stats Cards */}
      <Grid container spacing={3} sx={{ mt: 1 }}>
        <StatCard title={t('dashboard_home.total_employees')} value={stats?.total_active} icon={<PeopleIcon />} color="#1976d2" />
        <StatCard title={t('dashboard_home.new_this_month')} value={stats?.new_this_month} icon={<PersonAddIcon />} color="#2e7d32" />
        <StatCard title={t('dashboard_home.retired_this_year')} value={stats?.retired_this_year} icon={<TrendingDownIcon />} color="#ed6c02" />
        <StatCard title={t('dashboard_home.on_leave_count')} value={stats?.on_leave} icon={<EventBusyIcon />} color="#9c27b0" />
        <StatCard title={t('dashboard_home.expired_documents')} value={stats?.expired_documents} icon={<WarningAmberIcon />} color="#d32f2f" />
        <StatCard title={t('dashboard_home.expiring_contracts')} value={stats?.expiring_contracts} icon={<AssignmentIcon />} color="#0288d1" />
      </Grid>

      <Grid container spacing={3} sx={{ mt: 1 }}>
        {/* Alerts */}
        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 2, mt: 3 }}>
            <Typography variant="h6" gutterBottom>{t('dashboard_home.alerts_title')}</Typography>
            <Divider sx={{ mb: 1 }} />
            {(alerts?.total_alerts === 0) ? (
              <Typography color="textSecondary">{t('dashboard_home.no_alerts')}</Typography>
            ) : (
              <List dense>
                {alerts?.expiring_documents?.slice(0, 5).map(doc => (
                  <ListItem key={`doc-${doc.id}`}>
                    <ListItemIcon><WarningAmberIcon color="warning" fontSize="small" /></ListItemIcon>
                    <ListItemText primary={doc.title} secondary={`${doc.employee_name} - ${doc.days_left} ${t('documents.days_left', { days: doc.days_left })}`} />
                  </ListItem>
                ))}
                {alerts?.expiring_contracts?.slice(0, 5).map(emp => (
                  <ListItem key={`ctr-${emp.id}`}>
                    <ListItemIcon><AssignmentIcon color="info" fontSize="small" /></ListItemIcon>
                    <ListItemText primary={emp.full_name} secondary={`${t('employees.contract_end_date')}: ${emp.contract_end_date}`} />
                  </ListItem>
                ))}
              </List>
            )}
          </Paper>
        </Grid>

        {/* Recent Activities */}
        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 2, mt: 3 }}>
            <Typography variant="h6" gutterBottom>{t('dashboard_home.recent_activities')}</Typography>
            <Divider sx={{ mb: 1 }} />
            {(!activities || activities.length === 0) ? (
              <Typography color="textSecondary">{t('dashboard_home.no_activities')}</Typography>
            ) : (
              <List dense>
                {activities.slice(0, 10).map(act => (
                  <ListItem key={act.id}>
                    <ListItemText
                      primary={act.description}
                      secondary={`${act.user} - ${act.action}`}
                    />
                  </ListItem>
                ))}
              </List>
            )}
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default DashboardPage;
